export const ConsumedBudgetSchema = z.object({
  cycles: nonNegativeInt().default(0),
  depth: nonNegativeInt().default(0),
  memoryOps: nonNegativeInt().default(0),
  llmCalls: nonNegativeInt().default(0),
});
export type ConsumedBudget = z.infer<typeof ConsumedBudgetSchema>;

export const TerminationReasonSchema = z.enum(TERMINATION_REASONS);
export type TerminationReason = z.infer<typeof TerminationReasonSchema>;

export const zeroConsumed = (): ConsumedBudget => ({ cycles: 0, depth: 0, memoryOps: 0, llmCalls: 0 });

export const ReasoningBudgetSchema = z.object({
  maxCycles: positiveInt(),
  maxDepth: positiveInt(),
  maxMemoryOps: positiveInt(),
  maxLMCalls: nonNegativeInt(),
  wallclockDeadlineMs: positiveInt().optional(),
  abortSignal: z.unknown().optional(),
  terminationReason: TerminationReasonSchema.optional(),
  consumed: ConsumedBudgetSchema.default(zeroConsumed),
});
export type ReasoningBudget = z.infer<typeof ReasoningBudgetSchema>;

export const BudgetGateInputSchema = z.object({
  budget: ReasoningBudgetSchema.optional(),
  operation: BudgetOperationSchema,
  estimatedCost: positiveInt().optional(),
  scopeId: z.union([z.enum(BUDGET_SCOPE_IDS), z.string()]).optional(),
  correlationId: z.string().optional(),
});
export type BudgetGateInput = z.infer<typeof BudgetGateInputSchema>;

export const BudgetGateOutputSchema = z.object({
  granted: z.boolean(),
  updatedBudget: ReasoningBudgetSchema.optional(),
  terminationReason: z.enum(TERMINATION_REASONS).optional(),
});
export type BudgetGateOutput = z.infer<typeof BudgetGateOutputSchema>;

export type GateName = 'perception' | 'action' | 'reward' | 'budget';

/** The decision shape: a grant, and why not when refused. */
export type Verdict<Granted extends string, Reason extends string = 'reason'> = {
  [K in Granted]: boolean;
} & {
  [K in Reason]?: string;
};

export type GateOutcome = Verdict<'granted'>;

export const PerceptionGateOutputSchema = z.object({
  admitted: z.boolean(),
  task: TaskAdmittedEventSchema.shape.payload.optional(),
  rejectionReason: z.string().optional(),
});
export type PerceptionGateOutput = z.infer<typeof PerceptionGateOutputSchema>;

export const CognitiveEventSchema = z.discriminatedUnion('type', [
  TaskAdmittedEventSchema,
  DerivationAcceptedEventSchema,
  DerivationRecordEventSchema,
  BeliefRevisedEventSchema,
  ConceptActivatedEventSchema,
  BudgetExhaustedEventSchema,
  BudgetConsumedEventSchema,
  PolicyViolationEventSchema,
  AutonomyModeChangedEventSchema,
  SelfModProposalEventSchema,
  JudgmentResolvedEventSchema,
  GatePassedEventSchema,
  GateFailedEventSchema,
  EgressGateRejectedEventSchema,
  ShadowValidationDropEventSchema,
  ProposalSubmittedEventSchema,
  ProposalAdmittedEventSchema,
  ProposalRejectedEventSchema,
  SnapshotCreatedEventSchema,
  SnapshotRestoredEventSchema,
  ...NarEventSchemas,
]);

export type CognitiveEvent = z.infer<typeof CognitiveEventSchema>;
export type TaskAdmittedEvent = z.infer<typeof TaskAdmittedEventSchema>;
export type DerivationAcceptedEvent = z.infer<typeof DerivationAcceptedEventSchema>;
export type DerivationRecordEvent = z.infer<typeof DerivationRecordEventSchema>;
export type BeliefRevisedEvent = z.infer<typeof BeliefRevisedEventSchema>;
export type ConceptActivatedEvent = z.infer<typeof ConceptActivatedEventSchema>;
export type BudgetExhaustedEvent = z.infer<typeof BudgetExhaustedEventSchema>;
export type BudgetConsumedEvent = z.infer<typeof BudgetConsumedEventSchema>;
export type PolicyViolationEvent = z.infer<typeof PolicyViolationEventSchema>;
export type AutonomyModeChangedEvent = z.infer<typeof AutonomyModeChangedEventSchema>;
export type SelfModProposalEvent = z.infer<typeof SelfModProposalEventSchema>;
export type GatePassedEvent = z.infer<typeof GatePassedEventSchema>;
export type GateFailedEvent = z.infer<typeof GateFailedEventSchema>;
export type EgressGateRejectedEvent = z.infer<typeof EgressGateRejectedEventSchema>;
export type ShadowValidationDropEvent = z.infer<typeof ShadowValidationDropEventSchema>;
export type ProposalSubmittedEvent = z.infer<typeof ProposalSubmittedEventSchema>;
export type ProposalAdmittedEvent = z.infer<typeof ProposalAdmittedEventSchema>;
export type ProposalRejectedEvent = z.infer<typeof ProposalRejectedEventSchema>;
export type SnapshotCreatedEvent = z.infer<typeof SnapshotCreatedEventSchema>;
export type SnapshotRestoredEvent = z.infer<typeof SnapshotRestoredEventSchema>;

export type CognitiveEventOf<T extends CognitiveEvent['type']> = Extract<CognitiveEvent, { type: T }>;

export const validateCognitiveEvent = (data: unknown) => CognitiveEventSchema.parse(data);
export const validateProposal = (data: unknown) => ProposalSchema.parse(data);
export const validateFormalizationCandidate = (data: unknown) => FormalizationCandidateSchema.parse(data);
export const validateFormalizationBatch = (data: unknown) => FormalizationBatchSchema.parse(data);
export const validateDerivationRecord = (data: unknown) => DerivationRecordSchema.parse(data);
export const validateReasoningBudget = (data: unknown) => ReasoningBudgetSchema.parse(data);
export const validateRuleTable = (data: unknown) => RuleTableSchema.parse(data);

export const isNarEvent = (e: CognitiveEvent): e is Extract<CognitiveEvent, { engine: 'nar' }> => e.engine === 'nar';

export const isEventType = <T extends CognitiveEvent['type']>(type: T) => (e: CognitiveEvent): e is Extract<CognitiveEvent, { type: T }> => e.type === type;

type Mintable<T extends CognitiveEvent['type']> = Omit<
  CognitiveEventOf<T>,
  'type' | 'engine' | 'timestamp' | 'correlationId' | 'causationId'
> & {
  engine: CognitiveEvent['engine'];
  timestamp?: number;
  correlationId?: string;
  causationId?: string;
};

export const mintCognitiveEvent = <T extends CognitiveEvent['type']>(
  type: T,
  draft: Mintable<T>
): CognitiveEventOf<T> =>
  ({
    ...draft,
    type,
    timestamp: draft.timestamp ?? Date.now(),
    correlationId: draft.correlationId ?? generateId('corr'),
  }) as CognitiveEventOf<T>;
